"use client";
import { MapContainer, TileLayer, Marker, Popup, useMap, Polyline, Tooltip } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';
import { useEffect } from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { FaMapMarkerAlt, FaStreetView } from 'react-icons/fa';
import { Destination } from '@/types';

// Component to handle map center updates
function ChangeView({ center, zoom }: { center: [number, number], zoom: number }) {
  const map = useMap();
  useEffect(() => {
    map.setView(center, zoom);
    // Force a resize to fix any rendering issues
    setTimeout(() => {
      map.invalidateSize();
    }, 100);
  }, [center, zoom, map]);
  return null;
}

// Create custom marker icons
const createCustomIcon = (color: string) => {
  const iconMarkup = renderToStaticMarkup(
    <div style={{ color: color, filter: 'drop-shadow(0px 3px 2px rgba(0,0,0,0.3))', transform: 'translate(-50%, -100%)' }}>
      <FaMapMarkerAlt size={40} />
    </div>
  );
  
  return L.divIcon({
    html: iconMarkup,
    className: 'custom-marker-icon', // distinct class to avoid default styles
    iconSize: [40, 40],
    iconAnchor: [20, 40], // Point of the icon which will correspond to marker's location
    popupAnchor: [0, -40] // Point from which the popup should open relative to the iconAnchor
  });
};

const defaultIcon = createCustomIcon('#00a8cc'); // Primary color
const selectedIcon = createCustomIcon('#ff6b6b'); // Accent color
const userLocationIcon = L.divIcon({
  html: renderToStaticMarkup(
    <div style={{ color: '#ffa500', filter: 'drop-shadow(0px 3px 2px rgba(0,0,0,0.3))', transform: 'translate(-50%, -100%)' }}>
      <FaStreetView size={40} />
    </div>
  ),
  className: 'custom-user-icon',
  iconSize: [40, 40],
  iconAnchor: [20, 40],
  popupAnchor: [0, -40]
});


interface MapProps {
  center: [number, number];
  zoom: number;
  destinations: Destination[];
  selectedId?: string;
  userLocation?: [number, number];
}

export default function MapComponent({ center, zoom, destinations, selectedId, userLocation }: MapProps) {
  const selectedDest = destinations.find(d => d.id === selectedId);

  return (
    <MapContainer 
      center={center} 
      zoom={zoom} 
      scrollWheelZoom={false} 
      style={{ height: "100%", width: "100%", borderRadius: "inherit", zIndex: 1 }}
      className="rounded-4"
    >
      <ChangeView center={center} zoom={zoom} />
      <TileLayer
        attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors &copy; <a href="https://carto.com/attributions">CARTO</a>'
        url="https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png"
      />
      
      {/* Route Path */}
      {userLocation && selectedDest && (
        <>
          <Marker position={userLocation} icon={userLocationIcon}>
             <Popup className="custom-popup">
                <div className="fw-bold text-center p-2">You are here</div>
             </Popup>
          </Marker>
          <Polyline 
            positions={[userLocation, [selectedDest.latitude, selectedDest.longitude]]}
            pathOptions={{ color: '#00a8cc', dashArray: '10, 10', weight: 4, opacity: 0.8 }} 
          />
        </>
      )}

      {destinations.map((dest) => (
        <Marker 
            key={dest.id} 
            position={[dest.latitude, dest.longitude]} 
            icon={selectedId === dest.id ? selectedIcon : defaultIcon}
            opacity={selectedId && selectedId !== dest.id ? 0.6 : 1}
        >
          <Tooltip direction="top" offset={[0, -45]} opacity={1} className="fw-bold px-2 py-1 rounded shadow-sm border-0">
            {dest.name}
          </Tooltip>
          <Popup className="custom-popup" closeButton={false}>
            <div className="card border-0 shadow-none" style={{ width: "200px" }}>
              <div className="position-relative">
                <img 
                  src={dest.imageUrl} 
                  alt={dest.name} 
                  className="card-img-top rounded-top"
                  style={{ height: "120px", objectFit: "cover" }} 
                />
                <span className="badge bg-white text-primary position-absolute top-0 end-0 m-2 shadow-sm">
                  {dest.category}
                </span>
              </div>
              <div className="card-body p-3 text-center">
                <h6 className="card-title fw-bold mb-1">{dest.name}</h6>
                <div className="text-warning small mb-2">★★★★☆</div>
                <a 
                  href={`/destination/${dest.id}`} 
                  className="btn btn-sm btn-outline-primary w-100 rounded-pill fw-bold"
                >
                  View Details
                </a>
              </div>
            </div>
          </Popup>
        </Marker>
      ))}
      
      <style jsx global>{`
        .leaflet-popup-content-wrapper {
          padding: 0;
          border-radius: 1rem;
          overflow: hidden;
          box-shadow: 0 10px 25px rgba(0,0,0,0.15);
        }
        .leaflet-popup-content {
          margin: 0;
          width: 201px !important;
        }
        .leaflet-container {
          font-family: var(--font-sans);
        }
      `}</style>
    </MapContainer>
  );
}
